<script setup lang="ts">
import type {AccountView,AccountInput,CarrierProvider} from '../types';
import { computed, reactive } from 'vue';
const props=withDefaults(defineProps<{account:AccountView|null;busy:boolean;error:string;readonly?:boolean;provider?:CarrierProvider}>(),{provider:'ANE'});
const isYimi=computed(()=>props.provider==='YIMI');
const emit=defineEmits<{save:[input:AccountInput]}>();
const draft=reactive<AccountInput>({version:props.account?.version??0,code:props.account?.code??'',customerCode:props.account?.customerCode??'',dictId:props.account?.dictId??'',orderUrl:props.account?.orderUrl??'',appKey:'',customerPass:'',appSecret:'',yimi:{sellerId:props.account?.yimi?.sellerId??'',subscriptionId:props.account?.yimi?.subscriptionId??'',designatedPickup:Boolean(props.account?.yimi?.designatedPickup || props.account?.yimi?.salesmanCode?.trim() || props.account?.yimi?.salesmanName?.trim()),salesmanCode:props.account?.yimi?.salesmanCode??'',salesmanName:props.account?.yimi?.salesmanName??''},sender:props.account?{...props.account.sender}:{name:'',phone:'',province:'',city:'',county:'',address:''}});
const changed=computed(()=>!!props.account && (isYimi.value
  ? Boolean(draft.appKey?.trim()) || draft.yimi?.sellerId!==props.account.yimi?.sellerId || draft.yimi?.subscriptionId!==props.account.yimi?.subscriptionId
  : ['code','customerCode','dictId'].some(field=>draft[field as 'code']!==props.account![field as 'code'])));
const runtimeEnvironment=import.meta.env.VITE_RUNTIME_ENV??(import.meta.env.PROD?'prod':'local');
const environment=computed(()=>props.account?.environment??(runtimeEnvironment==='prod'?'production':'test'));
function changeDesignatedPickup(event:Event){
  if(!draft.yimi)return;
  draft.yimi.designatedPickup=(event.target as HTMLInputElement).checked;
  if(!draft.yimi.designatedPickup){draft.yimi.salesmanCode='';draft.yimi.salesmanName='';}
}
function save(){
  const {appKey,customerPass,appSecret,yimi,...input}=draft;
  emit('save',{...input,sender:{...input.sender},...(appKey?.trim()?{appKey:appKey.trim()}:{}),
    ...(isYimi.value?{yimi:{sellerId:yimi?.sellerId??'',subscriptionId:yimi?.subscriptionId??'',designatedPickup:Boolean(yimi?.designatedPickup),salesmanCode:yimi?.salesmanCode?.trim()??'',salesmanName:yimi?.salesmanName?.trim()??''},...(appSecret?.trim()?{appSecret:appSecret.trim()}:{})}
      :customerPass?.trim()?{customerPass:customerPass.trim()}:{})});
}
</script>
<template><form class="space-y-5" data-testid="account-form" autocomplete="off" @submit.prevent="save"><div class="flex flex-wrap items-center gap-3 rounded-lg bg-slate-50 p-4 text-sm"><strong>{{ environment==='production'?'正式环境':'测试环境' }}</strong><span :class="account?.ready?'text-emerald-600':'text-amber-700'">{{ account?.ready?'接口配置完整':account?.message || '尚未保存数据库账号' }}</span></div><p v-if="error" role="alert" class="rounded bg-rose-50 p-3 text-sm text-rose-700">{{ error }}</p><p v-if="changed" role="alert" class="rounded bg-amber-50 p-3 text-sm text-amber-800">账号身份已变更，将建立新账号；留空密钥不会从原账号转移，请重新填写新账号密钥。</p><fieldset :disabled="busy || readonly" class="grid gap-5 md:grid-cols-2"><label v-if="!isYimi">账号编码 code<input v-model.trim="draft.code" name="account-code" class="control" maxlength="100"></label><label v-if="!isYimi">客户编码 customerCode<input v-model.trim="draft.customerCode" class="control" maxlength="100"></label><label v-if="!isYimi">字典标识 dictId<input v-model.trim="draft.dictId" class="control" maxlength="100"></label><label v-if="!isYimi">下单服务地址（HTTPS）<input v-model.trim="draft.orderUrl" class="control" maxlength="500" placeholder="填写承运商受控服务地址"></label><p v-else class="self-center text-xs text-slate-500">壹米电子面单网关随系统环境固定。商家或订购ID未补全时可保存和估价，补全后才能接口下单。</p><label>appKey <span class="text-xs text-slate-400">{{ account?.appKeyConfigured?'已配置，留空保留':'尚未配置' }}</span><input v-model="draft.appKey" name="appKey" type="password" autocomplete="new-password" class="control" maxlength="1000" placeholder="输入新密钥以替换"></label><label v-if="isYimi">appSecret <span class="text-xs text-slate-400">{{ account?.appSecretConfigured?'已配置，留空保留':'尚未配置' }}</span><input v-model="draft.appSecret" name="appSecret" type="password" autocomplete="new-password" class="control" maxlength="1000" placeholder="输入新密钥以替换"></label><label v-if="isYimi && draft.yimi">商家ID sellerId<input v-model.trim="draft.yimi.sellerId" name="sellerId" class="control" maxlength="100"></label><label v-if="isYimi && draft.yimi">订购ID subscriptionId<input v-model.trim="draft.yimi.subscriptionId" name="subscriptionId" class="control" maxlength="100"></label>
<label v-if="isYimi && draft.yimi" class="md:col-span-2"><span class="flex items-center gap-2"><input name="designatedPickup" type="checkbox" :checked="draft.yimi.designatedPickup" @change="changeDesignatedPickup">指定揽收业务员（汇森/汇霖）</span></label>
<template v-if="isYimi && draft.yimi?.designatedPickup">
  <label>揽收业务员工号 <span class="text-rose-600">必填</span><input v-model.trim="draft.yimi.salesmanCode" name="salesmanCode" class="control" maxlength="50" aria-required="true"></label>
  <label>揽收业务员姓名 <span class="text-rose-600">必填</span><input v-model.trim="draft.yimi.salesmanName" name="salesmanName" class="control" maxlength="50" aria-required="true"></label>
  <p class="text-xs text-amber-700 md:col-span-2">可保存配置；指定揽收的工号和姓名补全后才能接口下单。关闭指定揽收会清空工号和姓名。</p>
</template>
<label v-if="!isYimi">customerPass <span class="text-xs text-slate-400">{{ account?.customerPassConfigured?'已配置，留空保留':'尚未配置' }}</span><input v-model="draft.customerPass" name="customerPass" type="password" autocomplete="new-password" class="control" maxlength="1000" placeholder="输入新密钥以替换"></label><h3 class="border-t pt-4 font-semibold text-slate-800 md:col-span-2">默认寄件资料</h3><label>寄件人<input v-model.trim="draft.sender.name" class="control" maxlength="100"></label><label>联系电话<input v-model.trim="draft.sender.phone" class="control" maxlength="50" type="tel"></label><label>省<input v-model.trim="draft.sender.province" class="control" placeholder="完整省级名称"></label><label>市<input v-model.trim="draft.sender.city" class="control"></label><label>区 / 县<input v-model.trim="draft.sender.county" class="control"></label><label class="md:col-span-2">详细地址<input v-model.trim="draft.sender.address" class="control" maxlength="500"></label></fieldset><p class="text-xs text-slate-500">环境由当前系统固定；保存配置不会发起真实物流请求。密钥仅供替换输入，服务器不会返回原密钥。</p><div v-if="!readonly" class="text-right"><button :disabled="busy" class="rounded-lg bg-indigo-500 px-5 py-2 text-sm font-semibold text-white disabled:opacity-40">{{ busy?'保存中…':'保存账号及寄件资料' }}</button></div></form></template>
<style scoped>label{@apply block text-sm text-slate-600;}.control{@apply mt-2 block w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-800 outline-none focus:border-indigo-400;}</style>
